    def _handle_chat(self, obj: dict):
        # message
        if not self.user:
            return

        to = obj.get('to')
        text = obj.get('text', '')
        group_field = obj.get('group')
        broadcast_all = obj.get('broadcast', False)

        msg_id = self.server.get_next_msg_id()
